import numpy as np
def equation(t,P,params):
    b,g,a0,a1,a2,a3,c0,c1,c2=params[0:9]
    T=np.tanh(b*t)
    S=1-np.exp(-g*t)
    return T*(a0+a1*P+a2*P**2+a3*P**3)+S*(c0+c1*P+c2*P**2)
